"""Local-only population/HUD and cross-building admission acceptance with real training clicks."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--url',default='http://127.0.0.1:8021');p.add_argument('--expected-commit',required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();assert a.url.startswith('http://127.0.0.1:');a.out.mkdir(parents=True,exist_ok=True)
r={'stage':'AFTER_LOCAL','fixture':'synthetic seeded population-boundary scene; real Start/Train/Pause/Save/Continue clicks; disposable local save','console':[],'errors':[],'failed':[],'tests':[]}
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);c=b.new_context(viewport={'width':1600,'height':1100},record_har_path=str(a.out/'network.har'));page=c.new_page();page.on('console',lambda m:r['console'].append({'type':m.type,'text':m.text}));page.on('pageerror',lambda e:r['errors'].append(str(e)));page.on('requestfailed',lambda q:r['failed'].append({'url':q.url,'error':q.failure}));c.tracing.start(screenshots=True,snapshots=True)
 def check(name,s,ok):r['tests'].append({'name':name,'observed':s,'pass':bool(ok)});assert ok,(name,s)
 def sample():return page.evaluate("()=>{const g=ageOfAsh.game;return {mil:g.militaryPopulation,milCap:g.militaryPopCap,eco:g.economicPopulation,ecoCap:g.economicPopCap,queuedMil:g.queuedPopulation(false),queuedEco:g.queuedPopulation(true),resources:{...g.resources},queues:g.buildings.map(b=>({id:b.id,type:b.type,queue:b.queue}))}}")
 def select(id):page.evaluate('id=>ageOfAsh.game.setSelection([ageOfAsh.game.buildings.find(b=>b.id===id)])',id)
 try:
  page.goto(a.url);page.wait_for_function('!!window.ageOfAsh');r['manifest']=c.request.get(a.url+'/__qa_build.json').json();assert r['manifest']['commit']==a.expected_commit and not r['manifest']['dirty'];r['browser']=b.version
  page.locator('#setup-civ').select_option('TEU');page.locator('#setup-biome').select_option('steppe');page.locator('#btn-start').click();s=sample();check('normal-start four HUD fields finite',s,all(isinstance(s[k],(int,float)) for k in ['mil','milCap','eco','ecoCap']));r['initial_cap_spec_status']='SPEC_DECISION_REQUIRED: legacy housing yields30, GDD states40; no balance reconciliation in this slice'
  ids=page.evaluate("""()=>{const g=ageOfAsh.game;g.units=[];g.hero=null;g.buildings=[];g.selection=[];g.world.resources=[];g.autoEconomy=false;g.autoMilitary=false;g.phase='prep';g.prepTimer=1e6;g.resources={food:10000,wood:10000,gold:10000,stone:10000};for(const t of g.world.tiles)t.terrain='grass';g.world.seed++;ageOfAsh.renderer.terrainKey='';const core=g.addBuilding('core',23,25,true),a=g.addBuilding('barracks',20,20,true),b=g.addBuilding('barracks',28,20,true);for(let i=0;i<9;i++)g.spawnUnit('militia',18+i%3*1.2,28+Math.floor(i/3)*1.2);g.camera={x:0,y:480,targetX:0,targetY:480,zoom:1,targetZoom:1};return [core.id,a.id,b.id];}""")
  select(ids[1]);page.locator('[data-command="train:militia"]').click();s=sample();check('first training click reserves final military slot',s,s['queuedMil']==1);before=s['resources'];select(ids[2]);page.locator('[data-command="train:militia"]').click();s=sample();check('second building rejected with zero additional spending',s,s['queuedMil']==1 and s['resources']==before)
  select(ids[0]);page.locator('[data-command="train:villager"]').click();s=sample();check('economy trains independently of full military reservation',s,s['queuedEco']==1 and s['queuedMil']==1);page.screenshot(path=str(a.out/'population-reservations.png'))
  page.locator('#btn-pause').click();s=sample();page.locator('#btn-save').click();page.reload();page.locator('#btn-continue').click();after=sample();check('real Save/Load preserves both queue reservations',after,after['queuedMil']==s['queuedMil'] and after['queuedEco']==s['queuedEco']);page.screenshot(path=str(a.out/'population-loaded.png'))
  check('no console/page/request errors',{'console':r['console'],'page':r['errors'],'failed':r['failed']},not r['errors'] and not r['failed'] and not any(m['type']=='error' for m in r['console']));r['pass']=True
 except Exception as e:r['pass']=False;r['error']=str(e);page.screenshot(path=str(a.out/'failure.png'))
 finally:c.tracing.stop(path=str(a.out/'trace.zip'));c.close();b.close();(a.out/'results.json').write_text(json.dumps(r,ensure_ascii=False,indent=2))
print(json.dumps({'pass':r['pass'],'checks':[(x['name'],x['pass']) for x in r['tests']],'error':r.get('error')}));raise SystemExit(0 if r['pass'] else 1)
